"""Result tables generated from the run log (task M4; PLAN §10 "tables generated by code").

`cost_grid_table` reads experiments.jsonl and each run's results/<run_id>/daily.parquet.
Costs are linear and the gross path doesn't depend on them (the engine drifts weights on gross
returns), so net returns at any per-side cost c are exactly gross - traded * c - borrow.
Every row is first checked against its logged net Sharpe; a mismatch raises.
"""

from __future__ import annotations

import json
import math
from pathlib import Path

import pandas as pd

from edge_autopsy.metrics import sharpe


def _dev_rows(log_path: Path, phase: str) -> list[dict]:
    rows: dict[str, dict] = {}
    for line in Path(log_path).read_text(encoding="utf-8").splitlines():
        r = json.loads(line)
        if r.get("phase") == phase:
            rows[r["config_hash"]] = r  # identical re-run: keep the latest, first position
    return list(rows.values())


def cost_grid_table(log_path, root, rf: pd.Series, grid_bps, phase: str = "dev") -> pd.DataFrame:
    out = []
    for r in _dev_rows(log_path, phase):
        d = pd.read_parquet(Path(root) / r["results_path"] / "daily.parquet")
        lo, hi = r["split"]["eval"]
        d = d.loc[lo:hi]
        rfe = rf.reindex(d.index)
        gross = d["gross"]
        traded = d["traded"] if "traded" in d else gross * 0.0
        cost = d["cost"] if "cost" in d else gross * 0.0
        borrow = gross - d["net"] - cost

        def net_sharpe(c, gross=gross, traded=traded, borrow=borrow, rfe=rfe):
            return sharpe(gross - traded * c / 1e4 - borrow, rfe)

        logged = r["metrics"].get("sharpe_net")
        if logged is not None and not math.isclose(
            net_sharpe(r["cost_bps"]), logged, rel_tol=1e-9, abs_tol=1e-12
        ):
            raise ValueError(f"run {r['run_id']}: logged sharpe_net does not match its daily file")
        scheme = r["split"].get("scheme", "")
        m = r["metrics"]
        row = {
            "label": r["model"] if scheme.startswith("none") else f"{r['model']} ({scheme})",
            "run_id": r["run_id"],
            "ic_mean": m.get("ic_mean"),
            "ic_t_nw": m.get("ic_t_nw"),
            "oos_r2": m.get("oos_r2"),
            "sharpe_gross": sharpe(gross, rfe),
            **{f"sharpe_net_{c:g}bps": net_sharpe(c) for c in grid_bps},
            "turnover_ann": m.get("turnover_ann"),
        }
        mt = float(traded.mean())
        excess = float((gross - borrow - rfe).mean())
        row["break_even_bps"] = excess / mt * 1e4 if mt > 0 else None
        row["n_inner_trials"] = r.get("n_inner_trials", 0)
        out.append(row)
    return pd.DataFrame(out)


def _fmt(x) -> str:
    if x is None or (isinstance(x, float) and math.isnan(x)):
        return "—"
    if isinstance(x, float):
        return f"{x:.4f}" if abs(x) < 10 else f"{x:.1f}"
    return str(x)


def to_markdown(df: pd.DataFrame) -> str:
    cols = list(df.columns)
    lines = ["| " + " | ".join(cols) + " |", "|" + "---|" * len(cols)]
    for _, r in df.iterrows():
        lines.append("| " + " | ".join(_fmt(r[c]) for c in cols) + " |")
    return "\n".join(lines) + "\n"
